<?php
declare(strict_types=1);
require_once __DIR__.'/strategy_portfolio.php';

function strategy_review_portfolio(int$id,string$note):array{require_permission('portfolio_intelligence.review');$row=strategy_find_portfolio($id);if(!$row||$row['status']!=='draft')throw new RuntimeException('Portfolio is not awaiting review.');$uid=(int)current_user()['id'];if((int)$row['reviewer_user_id']!==$uid||in_array($uid,[(int)$row['owner_user_id'],(int)$row['approver_user_id']],true))throw new RuntimeException('Portfolio review must be independently assigned.');if(trim($note)==='')throw new RuntimeException('Portfolio review evidence is required.');$row['status']='reviewed';$row['evidence_note']=trim($row['evidence_note']).' Review: '.mb_substr(trim($note),0,3000);return strategy_save_portfolio($row);}
function strategy_review_change_proposal(int$id,string$note):array{require_permission('portfolio_intelligence.review');$row=strategy_find_change_proposal($id);if(!$row||$row['status']!=='submitted')throw new RuntimeException('Process-change proposal is not awaiting review.');$uid=(int)current_user()['id'];if((int)$row['reviewed_by']!==$uid||in_array($uid,[(int)$row['prepared_by'],(int)$row['approved_by']],true))throw new RuntimeException('Process-change review must remain independent.');if(trim($note)==='')throw new RuntimeException('Process-change review evidence is required.');$row['status']='reviewed';$row['review_note']=mb_substr(trim($note),0,5000);$row['reviewed_at']=date('Y-m-d H:i:s');return strategy_portfolio_save_row('enterprise_process_change_proposals','enterprise_process_change_proposals','strategy_portfolio_demo_change_proposals',$row,['initiative_id','proposal_number','process_id','process_version_id','process_step_id','proposed_change','reason','impact_json','status','prepared_by','reviewed_by','approved_by','evidence_note','review_note','approval_note','submitted_at','reviewed_at','approved_at','locked_at']);}
function strategy_approve_change_proposal(int$id,string$note):array{require_permission('portfolio_intelligence.approve');$row=strategy_find_change_proposal($id);if(!$row||$row['status']!=='reviewed')throw new RuntimeException('Process-change proposal requires independent review before approval.');$uid=(int)current_user()['id'];if((int)$row['approved_by']!==$uid||in_array($uid,[(int)$row['prepared_by'],(int)$row['reviewed_by']],true))throw new RuntimeException('Process-change approval must remain independent.');if(trim($note)==='')throw new RuntimeException('Process-change approval evidence is required.');$process=process_mapping_find_process((int)$row['process_id']);$version=$process?process_mapping_process_version($process):null;if(!$process||!$version||(int)$version['id']!==(int)$row['process_version_id'])throw new RuntimeException('The referenced published process version changed; prepare a new proposal.');$row['status']='approved';$row['approval_note']=mb_substr(trim($note),0,5000);$row['approved_at']=date('Y-m-d H:i:s');$row['locked_at']=$row['approved_at'];return strategy_portfolio_save_row('enterprise_process_change_proposals','enterprise_process_change_proposals','strategy_portfolio_demo_change_proposals',$row,['initiative_id','proposal_number','process_id','process_version_id','process_step_id','proposed_change','reason','impact_json','status','prepared_by','reviewed_by','approved_by','evidence_note','review_note','approval_note','submitted_at','reviewed_at','approved_at','locked_at']);}
function strategy_review_scenario(int$id,string$note):array{require_permission('portfolio_intelligence.review');$row=strategy_find_scenario($id);if(!$row||$row['status']!=='simulated')throw new RuntimeException('Scenario is not awaiting review.');$uid=(int)current_user()['id'];if((int)$row['reviewed_by']!==$uid||(int)$row['prepared_by']===$uid)throw new RuntimeException('Scenario review must remain independent.');if(trim($note)==='')throw new RuntimeException('Scenario review evidence is required.');$row['status']='reviewed';$row['evidence_note']=trim($row['evidence_note']).' Independent review: '.mb_substr(trim($note),0,3000);$row['reviewed_at']=date('Y-m-d H:i:s');$row['locked_at']=$row['reviewed_at'];return strategy_portfolio_save_row('enterprise_portfolio_scenarios','enterprise_portfolio_scenarios','strategy_portfolio_demo_scenarios',$row,['portfolio_id','scenario_number','scenario_type','scenario_name','budget_limit','capacity_limit_hours','priority_weights_json','results_json','selected_cost','selected_benefit','selected_capacity_hours','status','prepared_by','reviewed_by','evidence_note','idempotency_key','generated_at','reviewed_at','locked_at']);}
function strategy_cancel_initiative(int$id,string$note):array{require_permission('portfolio_intelligence.approve');$row=strategy_find_initiative($id);if(!$row||in_array($row['stage'],['completed','cancelled'],true))throw new RuntimeException('Initiative is already closed.');if((int)$row['approver_user_id']!==(int)current_user()['id']||(int)$row['owner_user_id']===(int)current_user()['id'])throw new RuntimeException('Only the assigned independent approver may cancel this initiative.');if(trim($note)==='')throw new RuntimeException('Cancellation evidence is required.');$row['stage']='cancelled';$row['health']='cancelled';$row['cancelled_at']=date('Y-m-d H:i:s');$row['locked_at']=$row['cancelled_at'];$row['evidence_note']=trim($row['evidence_note']).' Cancellation: '.mb_substr(trim($note),0,3000);return strategy_save_initiative($row);}
